export const legalText=sections=>sections.map(([heading,text])=>heading+'\n'+text).join('\n\n');
export function orderLegalSnapshot(items,{digital=false,service=false,at=Date.now()}={}){
 return {version:legalVersion,acceptedAt:at,provider,digitalConsent:digital?digitalConsent:null,serviceEarlyStart:service,serviceConsent:service?serviceConsent:null,terms:legalText(saleSections),withdrawal:legalText(withdrawalSections),items:items.map(p=>({id:p.id,name:p.name,price:p.price,description:p.description||'',contents:p.contents||'',formats:p.formats||'',license:productLicense(p),service:p.category==='Designservice'}))};
}

